; define.asm -- chapter 34: keys the player chooses
; generated by gen34.py
        INCLUDE "msx.inc"
        OUTPUT "define.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
ticks   EQU VARS                ; frames counted by isr
rows    EQU VARS + 16           ; the matrix: 11 bytes
keys    EQU VARS + 32           ; the five keys: a row and a mask each
spr     EQU VARS + 48           ; the figure: Y, X, pattern, colour
index   EQU VARS + 52           ; the key chosen: 8 x row + bit
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; Five keys chosen by the player: for each action, every key up, then the
; first one down, kept as its row and mask; a key taken already is refused.
; Then a figure moved with them: a pixel a frame, dark blue while FIRE is held.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: chapter 30's set at 32
        ld hl, shapes
        ld e, 4
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; sprite pattern 0: chapter 26's figure
        ld hl, figure
        ld bc, 32 << 8 | VDP_DATA
        otir
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E2          ; the display on, the signal, sprites of 16 x 16
        in a, (VDP_CTRL)
        ld b, 0                 ; action 0: UP
ask:    push bc
        ld a, b                 ; the mark at the action asked for
        add a, a
        add a, 3
        ld d, a
        ld e, 1
        call at
        ld a, '>'
        out (VDP_DATA), a
again:  call choose             ; D = the row, E = the mask
        pop hl                  ; H: the action
        push hl
        ld a, h
        or a
        jr z, .new              ; the first: nothing to compare
        ld b, h
        ld hl, keys
.same:  ld a, (hl)              ; a key taken already?
        inc hl
        cp d
        jr nz, .next
        ld a, (hl)
        cp e
        jr z, again             ; taken: wait for another
.next:  inc hl
        djnz .same
.new:   pop bc
        push bc
        ld a, b                 ; keys + 2 x action: the row and the mask
        add a, a
        ld hl, keys
        add a, l
        ld l, a
        ld (hl), d
        inc hl
        ld (hl), e
taken:  ld a, (index)           ; the name: names6 + 6 x (8 x row + bit)
        ld l, a
        ld h, 0
        add hl, hl
        ld e, l
        ld d, h
        add hl, hl
        add hl, de
        ld de, names6
        add hl, de
        pop bc
        push bc
        push hl
        ld a, b
        add a, a
        add a, 3
        ld d, a
        ld e, 1
        call at
        ld a, ' '               ; the mark off
        out (VDP_DATA), a
        ld e, 10
        call at
        pop hl
        ld b, 6
.name:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .name
        pop bc
        inc b
        ld a, b
        cp 5
        jr nz, ask
        ld hl, spr              ; the game: the figure at its start
        ld (hl), 112
        inc hl
        ld (hl), 120
        inc hl
        ld (hl), 0
        inc hl
        ld (hl), 1
play:   call frame
        VRAM_WRITE $1B00        ; the figure, in the lines not drawn
        ld hl, spr
        ld b, 4
        ld c, VDP_DATA
        otir
        ld a, $D0
        out (VDP_DATA), a
        ld hl, rows
        ld b, 11
        call scan
logic:  ld ix, spr
        ld hl, keys             ; UP
        call held
        jr nz, .down
        dec (ix + 0)
.down:  ld hl, keys + 2
        call held
        jr nz, .left
        inc (ix + 0)
.left:  ld hl, keys + 4
        call held
        jr nz, .right
        dec (ix + 1)
.right: ld hl, keys + 6
        call held
        jr nz, .fire
        inc (ix + 1)
.fire:  ld hl, keys + 8
        call held
        ld a, 1
        jr nz, .colour
        ld a, 4
.colour: ld (ix + 3), a
        jr play

; held: HL = an action's row and mask; Z if its key is held down. Uses A, DE, HL
held:   ld a, (hl)              ; the row
        inc hl
        ld e, (hl)              ; the mask
        ld hl, rows
        add a, l
        ld l, a
        ld a, (hl)              ; the row's keys
        and e                   ; 0: held
        ret

; frame: wait for the next frame, then the interrupts off
frame:  ei
        halt
        di
        ret

; anykey: the 11 rows into rows; Z if no key is held. Uses A, B, C, HL
anykey: ld hl, rows
        ld b, 11
        call scan
        ld hl, rows
        ld b, 11
        ld a, $FF
.and:   and (hl)
        inc hl
        djnz .and
        cp $FF
        ret

; choose: every key up, then one down: D = its row, E = its mask, and index
; (in the first row with a key held, the lowest). Uses A, B, C, HL
choose: call frame
        call anykey
        jr nz, choose           ; something still held: wait
.wait:  call frame
        call anykey
        jr z, .wait             ; nothing yet
        ld hl, rows
        ld d, 0
.row:   ld a, (hl)
        cp $FF
        jr nz, .bit
        inc hl
        inc d
        jr .row
.bit:   ld e, 1
        ld c, 0
.find:  rrca
        jr nc, .got             ; a 0: this one
        sla e
        inc c
        jr .find
.got:   ld a, d
        add a, a
        add a, a
        add a, a
        add a, c
        ld (index), a
        ret

; scan: B rows of the keyboard, from row 0, into the bytes from HL; a bit at 0
; is a key held down. Port C's top four bits drive the cassette motor and its
; output, the CAPS lamp and the click (chapter 3): they go back as they were.
; The interrupts must be off. Uses A, B, C, HL
scan:   in a, (PPI_C)           ; 12
        and $F0                 ;  8  the top four bits
        ld c, a                 ;  5  and row 0
.row:   ld a, c                 ;  5
        out (PPI_C), a          ; 12  the row
        in a, (PPI_B)           ; 12  its eight keys
        ld (hl), a              ;  8
        inc hl                  ;  7
        inc c                   ;  5  the next row
        djnz .row               ; 14 / 9
        ret                     ; 11

; isr: every frame, a frame counted. Keeps AF
isr:    push af
        in a, (VDP_CTRL)        ; the status: the signal down
        ld a, (ticks)
        inc a
        ld (ticks), a
        pop af
        ei
        ret

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
